const fs = require('fs');
const path = '/root/.hermes/image_cache/img_a15819e8dd6b.webp';
const imageBuffer = fs.readFileSync(path);
const base64 = imageBuffer.toString('base64');
const dataUrl = 'data:image/webp;base64,' + base64;

const html = `<!DOCTYPE html>
<html><body>
<h2>OCR Processing...</h2>
<pre id="result">Loading Tesseract.js...</pre>
<img id="srcImage" src="${dataUrl}" style="max-width:400px;display:none">
<script src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js"></script>
<script>
async function run() {
  try {
    const img = document.getElementById('srcImage');
    await new Promise(r => { if(img.complete) r(); else img.onload = r; });
    const worker = await Tesseract.createWorker('chi_sim+eng');
    const { data: { text, words, lines } } = await worker.recognize(img);
    document.getElementById('result').textContent = '=== FULL TEXT ===\\n' + text + '\\n\\n=== LINES ===\\n' + 
      lines.map(l => l.text).join('\\n');
    await worker.terminate();
  } catch(e) {
    document.getElementById('result').textContent = 'Error: ' + e.message + '\\n' + e.stack;
  }
}
run();
</script>
</body></html>`;

fs.writeFileSync('/tmp/ocr_page.html', html);
